def project_segments(text, start, end, segments, holes, masks, privacy_eligible=True):
    # Specification helper over ALREADY TYPED source segments, not a full parser.
    # No learned features/authority; masks and holes cannot be promoted.
    if not privacy_eligible:
        return {"status":"privacy_masked", "segments":[], "holes":list(holes), "masks":dict(masks)}
    if type(text) is not str or type(start) is not int or type(end) is not int or not 0<=start<end<=len(text):
        raise ValueError("invalid_source_extent")
    cursor=start; kept=[]; removed=[]; all_parts=[]
    for s in segments:
        a,b=s["start"],s["end"]; kind=s["kind"]
        if type(a) is not int or type(b) is not int or a!=cursor or not a<b<=end:
            raise ValueError("nonpartition_or_invalid_segment")
        value=text[a:b]; remove=s.get("remove",False)
        if remove and kind not in {"attachment","formatting"}:
            raise ValueError("semantic_or_marker_deletion")
        if remove and kind=="attachment" and (value.strip().lower() not in {"on","for"} or not s.get("parent_relation_recognized",False)):
            raise ValueError("unproved_attachment")
        if remove and kind=="formatting" and (value.strip() not in {"",",","."} or s.get("internal",False)):
            raise ValueError("internal_or_semantic_punctuation")
        part={"start":a,"end":b,"kind":kind,"text":value}
        (removed if remove else kept).append(part);all_parts.append(value);cursor=b
    if cursor!=end or "".join(all_parts)!=text[start:end]:
        raise ValueError("lossless_partition_failed")
    return {"status":"projected", "semantic_segments":kept,"removed_segments":removed,
            "raw_extent":[start,end],"roundtrip":text[start:end],"holes":list(holes),"masks":dict(masks)}
